<?php require_once __DIR__.'/../includes/bootstrap.php'; if(is_logged_in()) redirect('admin/index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $s=$pdo->prepare('SELECT * FROM users WHERE username=? AND is_active=1');$s->execute([trim($_POST['username'])]);$u=$s->fetch(); if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];redirect('admin/index.php');}$error='Anmeldung fehlgeschlagen.';} render_header('Anmelden'); ?><div class="row justify-content-center"><div class="col-md-5"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3 mb-3">Admin-Anmeldung</h1><?php if(isset($_GET['installed'])):?><div class="alert alert-success">Installation abgeschlossen.</div><?php endif?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="mb-3"><label class="form-label"><?=e(t('text.benutzername'))?></label><input class="form-control" name="username" required autofocus></div><div class="mb-3"><label class="form-label"><?=e(t('text.passwort'))?></label><input type="password" class="form-control" name="password" required></div><button class="btn btn-primary w-100">Anmelden</button></form></div></div></div></div><?php render_footer();
